"""P4 additive Genesis composer tests; no provider or autogenerated costs."""
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))
from app.astra_genesis.context_bridge import GenesisContextBridge


def component(name, provides, requires=(), cost=1, effort=1, maintenance=1):
    return {
        "id": name, "provides": list(provides), "requires": list(requires),
        "cost_units": cost, "effort_units": effort,
        "maintenance_units": maintenance,
    }


class GenesisCatalogTests(unittest.TestCase):
    def test_domain_neutral_composition_observes_dependencies_and_proxy_rank(self):
        catalog = [
            component("capture", ["capture"], cost=2),
            component("store", ["persist"], ["capture"], cost=2),
            component("deliver", ["deliver"], ["store"], cost=3),
            component("all_in_one", ["capture", "persist", "deliver"], cost=20),
        ]
        report = GenesisContextBridge.rank_declared_catalog(
            catalog, ["capture", "persist", "deliver"], top_n=3
        )
        self.assertEqual(report["status"], "STRUCTURAL_OPTIONS_ONLY")
        self.assertEqual(report["top_structures"][0]["component_ids"],
                         ["capture", "deliver", "store"])
        self.assertEqual(report["top_structures"][0]["dependency_order"],
                         ["capture", "store", "deliver"])
        self.assertEqual(report["top_structures"][0]["proxy_totals"]["cost_units"], 7)
        self.assertIn("UNVERIFIED", report["input_authority"])
        self.assertNotIn("financial_forecast", report)

    def test_no_feasible_solution_is_not_success(self):
        report = GenesisContextBridge.rank_declared_catalog(
            [component("input", ["capture"])], ["capture", "process"]
        )
        self.assertEqual(report["status"], "NO_FEASIBLE_STRUCTURE")
        self.assertEqual(report["top_structures"], [])

    def test_dependency_cycle_cannot_be_presented_as_solution(self):
        report = GenesisContextBridge.rank_declared_catalog(
            [component("a", ["capture"], ["b"]),
             component("b", ["deliver"], ["a"])], ["capture", "deliver"]
        )
        self.assertEqual(report["status"], "NO_FEASIBLE_STRUCTURE")

    def test_missing_dependencies_and_fabricated_metrics_fail_closed(self):
        with self.assertRaisesRegex(ValueError, "dependency"):
            GenesisContextBridge.rank_declared_catalog(
                [component("a", ["capture"], ["nonexistent"])], ["capture"]
            )
        with self.assertRaisesRegex(ValueError, "proxy"):
            GenesisContextBridge.rank_declared_catalog(
                [component("a", ["capture"], cost=float("nan"))], ["capture"]
            )
        with self.assertRaises(ValueError):
            GenesisContextBridge.rank_declared_catalog(
                [component(str(i), ["capture"]) for i in range(11)], ["capture"]
            )

    def test_existing_bridge_is_not_replaced_or_auto_promoted(self):
        brief = GenesisContextBridge.compose({
            "actionable": True,
            "intent": "Simplify invoice reconciliation",
            "problem": "Manual work wastes time",
            "desired_outcome": "Reconcile invoices faster",
            "domain": "accounting",
            "evidence": [{"message_id": "hn:123"}],
        })
        self.assertEqual(brief["kind"], "genesis_opportunity_brief_v1")
        self.assertEqual(brief["market_demand"], "UNKNOWN")
        self.assertEqual(brief["willingness_to_pay"], "UNKNOWN")
        self.assertNotIn("top_structures", brief)


if __name__ == "__main__":
    unittest.main()
